deck_path = WORK / '.build_v4/deck_v4.mjs'
deck_text = deck_path.read_text()
stages = json.loads(deck_text.split('export const stages=')[1].rstrip().removesuffix(';'))
assert len(stages) == len(scripts) == len(lessons) == 7
for i, (stage, beats) in enumerate(zip(stages, scripts)):
    stage['notes'] = '\n\n'.join(text for cue, text in beats)
    lessons[i]['title'] = stage['title']
    lessons[i]['beats'] = [dict(cue=cue, text=text) for cue, text in beats]
    lessons[i]['start'], lessons[i]['end'] = stage['start'], stage['end']
    lessons[i]['source'] = stage['source']
    for key in lessons[i]['terms']:
        assert key in terms, key

payload = dict(version='20261007-wording3', labels={
    'บทความ':'กลไกหรือผลที่อยู่ใน PDF พร้อมหน้าอ้างอิง',
    'พื้นฐาน':'ความรู้ประกอบสำหรับอ่านระบบ ไม่ใช่ผลวิจัยใหม่',
    'การวิเคราะห์':'การตีความหรือคำนวณจากหลักฐานที่ระบุ',
    'อุปมา':'ตัวอย่างเปรียบเทียบที่แต่งเพื่ออธิบาย',
    'ตัวอย่างต่อยอด':'บริบทสมมติที่บทความยังไม่ได้ทดสอบ'}, terms=terms, lessons=lessons)
serialized = json.dumps(payload, ensure_ascii=False, indent=2)
for forbidden in ('DivWy','โครงงาน','ผม','ดิฉัน','เรา','คุณ','พวกเรา'):
    assert forbidden.lower() not in serialized.lower(), forbidden
(WORK/'05_study/slide-learning.json').write_text(serialized+'\n')
(PORTAL/'assets/js/pubtime-lessons.js').write_text('/* Generated from work4/05_study/slide-learning.json. */\nwindow.PUBTIME_STUDY = '+serialized+';\n')

deck_path.write_text(deck_text.split('export const stages=')[0]+'export const stages='+json.dumps(stages,ensure_ascii=False,indent=2)+';\n')
(WORK/'.build_v4/speaker-notes.json').write_text(json.dumps(stages,ensure_ascii=False,indent=2)+'\n')
